void lora_send(uint8_t *data, size_t len) {
  lora_write_reg(REG_FIFO_ADDR, 0);
  lora_write_fifo(data, len);
  lora_set_mode(MODE_TX);
}

#include <esp_now.h>
#include <WiFi.h>

// Alici MAC adresi
uint8_t receiverMac[] = {0x24, 0x6F, 0x28, 0xAA, 0xBB, 0xCC};

typedef struct {
  float yaw;
  float pitch;
  float roll;
} HeadData;

HeadData head;

void setup() {
  WiFi.mode(WIFI_STA);
  esp_now_init();
  esp_now_peer_info_t peer = {};
  memcpy(peer.peer_addr, receiverMac, 6);
  esp_now_add_peer(&peer);
}

void loop() {
  readIMU(&head);
  esp_now_send(receiverMac, (uint8_t*)&head, sizeof(head));
  delay(10); // ~100 Hz guncelleme
}
